def bio_paragraphs(text):
    clean=(text or "").strip()
    if not clean:
        return "<p>Full trainer bio is pending office approval for the new site.</p>"
    sentences=[part.strip() for part in clean.replace("  "," ").split(". ") if part.strip()]
    groups=[". ".join(sentences[i:i+3]).rstrip(".")+"." for i in range(0,len(sentences),3)]
    return "".join(f"<p>{html.escape(part)}</p>" for part in groups)

def trainer_landing_href(record):
    page_slug = str(record.get("pageSlug") or record.get("slug") or "").replace("-", "")
    return f'/{page_slug}#contact'

def trainer_landing_shell(record):
    trainer_id=html.escape(record.get("slug") or "")
    name=html.escape(record.get("name") or "Lorenzo Trainer")
    location=html.escape(record.get("location") or "")
    title=f"Dog Trainer in {location} | {name} | Lorenzo's Dog Training Team"
    description=f"Professional dog obedience training and behavior modification with {name} in {location}, backed by Lorenzo's Dog Training Team."
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><link rel="icon" href="assets/ldtt-favicon.png"><link rel="stylesheet" href="trainer-backoffice/styles.css?v=20260806landingportal"></head><body class="public-site" data-trainer="{trainer_id}"><main id="publicSite"></main><script src="supabase-config.js"></script><script src="trainer-roster.js"></script><script src="trainer-backoffice/supabase.js?v={PORTAL_ASSET_VERSION}"></script><script src="trainer-backoffice/app.js?v=20260806landingportal"></script></body></html>'''

