    photo=html.escape(record["bioPhoto"])
    schedule_url=trainer_landing_href(record)
    body=f'''<section class="trainer-profile-hero" data-trainer-profile-slug="{html.escape(slug)}"><div class="container trainer-profile-grid"><figure class="trainer-profile-photo"><img src="{photo}" data-trainer-image-role="profileBioPhoto" alt="{name} trainer bio photo"></figure><article class="trainer-profile-copy"><span class="tag">{state}</span><h1>{name}</h1><p class="trainer-profile-location">{location}</p><p class="trainer-profile-summary">{summary}</p><div class="trainer-profile-actions"><a class="btn btn-red" href="{schedule_url}">Schedule This Trainer</a><a class="btn btn-outline" href="find-a-trainer.html">Back to Trainer Directory</a></div></article></div></section><section class="section trainer-profile-body"><div class="container trainer-profile-article"><span class="eyebrow">Trainer Bio</span><h2>About <span data-trainer-profile-name>{name}</span></h2><div data-trainer-profile-bio>{bio_paragraphs(record["bio"])}</div></div></section><section class="section soft"><div class="container"><div class="cta-band"><div><h2>Ready to start training with <span data-trainer-profile-name>{name}</span>?</h2><p>Send your request directly to Lorenzo's office with <span data-trainer-profile-name>{name}</span> already assigned as the source trainer.</p></div><a class="btn btn-red" href="{schedule_url}">Schedule This Trainer</a></div></div></section>'''
    return body

